import React from 'react';
import { useNavigate } from 'react-router-dom';
import { TOP_HEADER_PX } from '../config/thoughtspot';

const BG   = '#F0EEE7';
const INK  = '#0D0D0D';
const CARD = '#E8E4DA';

// ─── Tiny icon components ────────────────────────────────────────────────────

function IconPulse() {
  return (
    <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke={INK} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
      <polyline points="22 12 18 12 15 21 9 3 6 12 2 12" />
    </svg>
  );
}

function IconBell() {
  return (
    <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke={INK} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
      <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9" />
      <path d="M13.73 21a2 2 0 0 1-3.46 0" />
    </svg>
  );
}

function IconStar() {
  return (
    <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke={INK} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
      <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
    </svg>
  );
}

// ─── Notification card — simulates a live alert ──────────────────────────────

function LiveAlert({
  tag,
  text,
  detail,
  delay,
}: {
  tag: string;
  text: string;
  detail: string;
  delay: string;
}) {
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'flex-start',
        gap: 10,
        padding: '10px 12px',
        backgroundColor: '#FFFFFF',
        borderRadius: 8,
        border: '1px solid rgba(0,0,0,0.08)',
        animation: `fadeInUp 0.5s ease both`,
        animationDelay: delay,
      }}
    >
      <div
        style={{
          width: 8, height: 8, borderRadius: '50%', backgroundColor: INK,
          marginTop: 5, flexShrink: 0,
        }}
      />
      <div>
        <span
          style={{
            display: 'inline-block', fontSize: 10, fontWeight: 700,
            letterSpacing: '0.06em', textTransform: 'uppercase',
            color: 'rgba(0,0,0,0.40)', marginBottom: 2,
          }}
        >
          {tag}
        </span>
        <p style={{ fontSize: 13, fontWeight: 600, color: INK, margin: 0, lineHeight: 1.35 }}>{text}</p>
        <p style={{ fontSize: 12, color: 'rgba(0,0,0,0.45)', margin: '2px 0 0', lineHeight: 1.4 }}>{detail}</p>
      </div>
    </div>
  );
}

// ─── Feature card — mirrors VisioLab site cards ──────────────────────────────

function FeatureCard({
  icon,
  title,
  body,
  visual,
}: {
  icon: React.ReactNode;
  title: string;
  body: string;
  visual?: React.ReactNode;
}) {
  return (
    <div
      style={{
        flex: '1 1 0',
        minWidth: 240,
        backgroundColor: CARD,
        borderRadius: 14,
        border: '1px solid rgba(0,0,0,0.07)',
        padding: '1.5rem 1.5rem 1.25rem',
        display: 'flex',
        flexDirection: 'column',
        gap: 0,
      }}
    >
      <div style={{ flex: 1 }}>
        {visual && (
          <div style={{ marginBottom: '1.25rem' }}>{visual}</div>
        )}
      </div>
      <div>
        <div style={{ marginBottom: 8 }}>{icon}</div>
        <h3 style={{ fontSize: 16, fontWeight: 700, color: INK, margin: '0 0 6px', letterSpacing: '-0.025em' }}>
          {title}
        </h3>
        <p style={{ fontSize: 13, color: 'rgba(0,0,0,0.55)', lineHeight: 1.6, margin: 0 }}>
          {body}
        </p>
      </div>
    </div>
  );
}

// ─── Stat chip ───────────────────────────────────────────────────────────────

function StatChip({ value, label }: { value: string; label: string }) {
  return (
    <div style={{ textAlign: 'center' }}>
      <div style={{ fontSize: 32, fontWeight: 700, color: INK, letterSpacing: '-0.04em', lineHeight: 1 }}>
        {value}
      </div>
      <div style={{ fontSize: 12, color: 'rgba(0,0,0,0.50)', marginTop: 4, lineHeight: 1.3 }}>
        {label}
      </div>
    </div>
  );
}

// ─── Page ────────────────────────────────────────────────────────────────────

export default function HomePage() {
  const navigate = useNavigate();

  return (
    <div
      style={{
        backgroundColor: BG,
        minHeight: `calc(100vh - ${TOP_HEADER_PX}px)`,
        fontFamily: "'Manrope', -apple-system, BlinkMacSystemFont, sans-serif",
      }}
    >
      <style>{`
        @keyframes fadeInUp {
          from { opacity: 0; transform: translateY(8px); }
          to   { opacity: 1; transform: translateY(0); }
        }
      `}</style>

      {/* ── Hero ─────────────────────────────────────────────────────────── */}
      <div
        style={{
          maxWidth: 1080,
          margin: '0 auto',
          padding: '3.5rem 2.5rem 2rem',
        }}
      >
        {/* Badge pill — mirrors VisioLab "ONE SYSTEM. EVERY CAPABILITY." */}
        <div
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 6,
            backgroundColor: 'rgba(0,0,0,0.07)',
            borderRadius: 20,
            padding: '5px 12px',
            marginBottom: '1.5rem',
          }}
        >
          <span
            style={{
              fontSize: 10,
              fontWeight: 700,
              letterSpacing: '0.10em',
              textTransform: 'uppercase',
              color: 'rgba(0,0,0,0.55)',
            }}
          >
            Analyst Agent
          </span>
        </div>

        {/* Headline — mirrors "Visual Recognition. POS. Payment. All in One." */}
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '2rem', flexWrap: 'wrap' }}>
          <div style={{ flex: '1 1 420px', maxWidth: 560 }}>
            <h1
              style={{
                fontSize: 'clamp(32px, 4.5vw, 52px)',
                fontWeight: 700,
                color: INK,
                lineHeight: 1.1,
                letterSpacing: '-0.03em',
                margin: '0 0 1.25rem',
              }}
            >
              Monitor. Detect.{' '}
              <em style={{ fontStyle: 'italic', fontWeight: 700 }}>Act First.</em>
            </h1>
            <p
              style={{
                fontSize: 15,
                color: 'rgba(0,0,0,0.55)',
                lineHeight: 1.65,
                margin: '0 0 2rem',
                maxWidth: 460,
              }}
            >
              VisioHub Analytics runs an analyst agent alongside every operator —
              continuously watching live event and merchant data, detecting
              anomalies the moment they emerge, and pushing proactive
              recommendations before problems become losses.
            </p>
            <button
              type="button"
              onClick={() => navigate('/dashboard')}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 8,
                backgroundColor: INK,
                color: '#F7F6F5',
                border: 'none',
                padding: '12px 22px',
                borderRadius: 8,
                fontSize: 14,
                fontWeight: 600,
                cursor: 'pointer',
                letterSpacing: '-0.01em',
              }}
            >
              Explore your dashboard
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M5 12h14M12 5l7 7-7 7" />
              </svg>
            </button>
          </div>

          {/* Live alerts preview — right side */}
          <div
            style={{
              flex: '0 0 auto',
              width: 300,
              display: 'flex',
              flexDirection: 'column',
              gap: 8,
              paddingTop: 4,
            }}
          >
            <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'rgba(0,0,0,0.35)', marginBottom: 4 }}>
              Live feed
            </div>
            <LiveAlert
              tag="Anomaly · Merchant 04"
              text="Checkout time up 3s"
              detail="Avg. 18s → 21s over last 45 min. Investigate terminal queue."
              delay="0.1s"
            />
            <LiveAlert
              tag="Recommendation · Event 12"
              text='Stock up on Miller Lite'
              detail="Football game starts in 2h. Historical sell-through: 94% per event."
              delay="0.25s"
            />
            <LiveAlert
              tag="Alert · Merchant 11"
              text="Transaction volume −28%"
              detail="Below expected baseline. Possible terminal offline."
              delay="0.4s"
            />
          </div>
        </div>
      </div>

      {/* ── Feature cards ────────────────────────────────────────────────── */}
      <div
        style={{
          maxWidth: 1080,
          margin: '0 auto',
          padding: '0 2.5rem 3rem',
        }}
      >
        <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
          <FeatureCard
            icon={<IconPulse />}
            title="Live Event Monitoring"
            body="Tracks checkout times, transaction volumes, and item performance per event and merchant in real time. Every data point, every second."
            visual={
              <div style={{ height: 120, display: 'flex', alignItems: 'flex-end', gap: 4, paddingBottom: 4 }}>
                {[55, 72, 60, 88, 65, 92, 78, 84, 70, 95, 80, 68].map((h, i) => (
                  <div
                    key={i}
                    style={{
                      flex: 1,
                      height: `${h}%`,
                      backgroundColor: i === 10 ? INK : `rgba(0,0,0,${0.10 + i * 0.015})`,
                      borderRadius: '3px 3px 0 0',
                      transition: 'height 0.3s ease',
                    }}
                  />
                ))}
              </div>
            }
          />
          <FeatureCard
            icon={<IconBell />}
            title="Anomaly Detection"
            body="Instant alerts the moment metrics deviate from baseline — checkout time, transaction drop, or unusual patterns. Zero lag between signal and action."
            visual={
              <div style={{ height: 120, position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                {[1, 2, 3].map(i => (
                  <div key={i} style={{
                    position: 'absolute',
                    width: i * 60, height: i * 60,
                    borderRadius: '50%',
                    border: `1.5px solid rgba(0,0,0,${0.18 - i * 0.04})`,
                  }} />
                ))}
                <div style={{ width: 10, height: 10, borderRadius: '50%', backgroundColor: INK, zIndex: 1 }} />
              </div>
            }
          />
          <FeatureCard
            icon={<IconStar />}
            title="Smart Recommendations"
            body="Proactive suggestions powered by historical patterns and live context — from inventory prep to staffing — before the opportunity passes."
            visual={
              <div style={{ height: 120, display: 'flex', flexDirection: 'column', gap: 6, justifyContent: 'center' }}>
                {[
                  { label: 'Miller Lite', pct: 94 },
                  { label: 'Hotdogs', pct: 78 },
                  { label: 'Nachos', pct: 61 },
                ].map(item => (
                  <div key={item.label}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 3 }}>
                      <span style={{ fontSize: 11, color: 'rgba(0,0,0,0.55)' }}>{item.label}</span>
                      <span style={{ fontSize: 11, fontWeight: 600, color: INK }}>{item.pct}%</span>
                    </div>
                    <div style={{ height: 5, backgroundColor: 'rgba(0,0,0,0.10)', borderRadius: 3 }}>
                      <div style={{ height: '100%', width: `${item.pct}%`, backgroundColor: INK, borderRadius: 3 }} />
                    </div>
                  </div>
                ))}
              </div>
            }
          />
        </div>
      </div>

      {/* ── Stats strip ──────────────────────────────────────────────────── */}
      <div style={{ borderTop: '1px solid rgba(0,0,0,0.08)', borderBottom: '1px solid rgba(0,0,0,0.08)', backgroundColor: '#FFFFFF' }}>
        <div
          style={{
            maxWidth: 1080,
            margin: '0 auto',
            padding: '2rem 2.5rem',
            display: 'flex',
            gap: '2rem',
            flexWrap: 'wrap',
            justifyContent: 'space-between',
          }}
        >
          <StatChip value=">99%" label="Item recognition accuracy" />
          <StatChip value="3–6×" label="Transaction throughput vs. traditional checkout" />
          <StatChip value="< 3s" label="Anomaly detection latency" />
          <StatChip value="500+" label="Live systems worldwide" />
        </div>
      </div>

      {/* ── How it works ─────────────────────────────────────────────────── */}
      <div style={{ maxWidth: 1080, margin: '0 auto', padding: '3rem 2.5rem' }}>
        <div style={{ marginBottom: '2rem' }}>
          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.10em', textTransform: 'uppercase', color: 'rgba(0,0,0,0.40)', marginBottom: 10 }}>
            How it works
          </div>
          <h2 style={{ fontSize: 28, fontWeight: 700, color: INK, letterSpacing: '-0.03em', margin: 0 }}>
            The analyst that never sleeps.
          </h2>
        </div>

        <div style={{ display: 'flex', gap: 0, flexWrap: 'wrap' }}>
          {[
            {
              num: '01',
              title: 'Data streams in live',
              body: 'Every transaction, checkout duration, and item scan flows into VisioHub in real time — per event, per merchant, per minute.',
            },
            {
              num: '02',
              title: 'Agent watches for signals',
              body: 'The analyst agent compares live metrics against rolling baselines and historical event patterns, scoring every anomaly by severity.',
            },
            {
              num: '03',
              title: 'You get the right alert',
              body: 'Operators receive targeted, actionable notifications — not noise. Checkout time up 3s at merchant 04. Stock up on Miller Lite. Terminal offline.',
            },
          ].map((step, i) => (
            <div
              key={step.num}
              style={{
                flex: '1 1 240px',
                padding: '1.75rem',
                borderLeft: i === 0 ? 'none' : '1px solid rgba(0,0,0,0.08)',
              }}
            >
              <div style={{ fontSize: 13, fontWeight: 700, color: 'rgba(0,0,0,0.25)', marginBottom: 10, letterSpacing: '0.02em' }}>
                {step.num}
              </div>
              <h4 style={{ fontSize: 15, fontWeight: 700, color: INK, margin: '0 0 8px', letterSpacing: '-0.02em' }}>
                {step.title}
              </h4>
              <p style={{ fontSize: 13, color: 'rgba(0,0,0,0.50)', lineHeight: 1.6, margin: 0 }}>
                {step.body}
              </p>
            </div>
          ))}
        </div>
      </div>

      {/* ── CTA footer strip ─────────────────────────────────────────────── */}
      <div
        style={{
          backgroundColor: INK,
          margin: '0 2.5rem 3rem',
          borderRadius: 14,
          padding: '2.5rem',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '1.5rem',
          flexWrap: 'wrap',
          maxWidth: 1080 - 40,
          marginLeft: 'auto',
          marginRight: 'auto',
        }}
      >
        <div>
          <h3 style={{ fontSize: 22, fontWeight: 700, color: '#F7F6F5', letterSpacing: '-0.03em', margin: '0 0 6px' }}>
            Your venue. Fully optimised.
          </h3>
          <p style={{ fontSize: 14, color: 'rgba(247,246,245,0.55)', margin: 0 }}>
            Dive into live dashboards, ask Iris anything, or let the agent surface what matters.
          </p>
        </div>
        <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
          <button
            type="button"
            onClick={() => navigate('/analytics')}
            style={{
              backgroundColor: '#F7F6F5',
              color: INK,
              border: 'none',
              padding: '10px 20px',
              borderRadius: 7,
              fontSize: 14,
              fontWeight: 600,
              cursor: 'pointer',
              letterSpacing: '-0.01em',
            }}
          >
            Ask Iris
          </button>
          <button
            type="button"
            onClick={() => navigate('/dashboard')}
            style={{
              backgroundColor: 'rgba(247,246,245,0.12)',
              color: '#F7F6F5',
              border: '1px solid rgba(247,246,245,0.15)',
              padding: '10px 20px',
              borderRadius: 7,
              fontSize: 14,
              fontWeight: 600,
              cursor: 'pointer',
              letterSpacing: '-0.01em',
            }}
          >
            View dashboards
          </button>
        </div>
      </div>
    </div>
  );
}
